// Handles ONLY push events and notification clicks — registered at
// /push-sw.js, separate from the main PWA service worker (public/sw.js),
// which is generated by next-pwa/workbox at build time and would
// overwrite any hand-written code placed in that same file.
self.addEventListener("push", (event) => {
  let data = { title: "MSA Academy", body: "" };
  try {
    data = event.data.json();
  } catch {
    data.body = event.data?.text() || "";
  }
  event.waitUntil(
    self.registration.showNotification(data.title || "MSA Academy", {
      body: data.body || "",
      icon: "/icon-192.png",
      badge: "/icon-192.png",
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  event.waitUntil(clients.openWindow("/"));
});
